CREATE TABLE IF NOT EXISTS institution_feedback (id INT AUTO_INCREMENT PRIMARY KEY,institution_id INT NOT NULL,overall_rating INT NOT NULL,ui_rating INT NOT NULL,ease_of_use_rating INT NOT NULL,attendance_rating INT NOT NULL,payment_rating INT NOT NULL,performance_rating INT NOT NULL,support_rating INT NOT NULL,recommend_status ENUM('Yes','Maybe','No') NOT NULL,improvement_comment TEXT NULL,feature_request TEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX ix_feedback_institution(institution_id),INDEX ix_feedback_created(created_at),CONSTRAINT fk_feedback_institution FOREIGN KEY(institution_id) REFERENCES institutions(id),CHECK(overall_rating BETWEEN 1 AND 5),CHECK(ui_rating BETWEEN 1 AND 5),CHECK(ease_of_use_rating BETWEEN 1 AND 5),CHECK(attendance_rating BETWEEN 1 AND 5),CHECK(payment_rating BETWEEN 1 AND 5),CHECK(performance_rating BETWEEN 1 AND 5),CHECK(support_rating BETWEEN 1 AND 5)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
